#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np(n);
        // [C, B, A]: C=p[n-y..n-1], B=p[x..n-y-1], A=p[0..x-1]
        int idx=0;
        for(int i=n-y;i<n;i++) np[idx++]=p[i];
        for(int i=x;i<n-y;i++) np[idx++]=p[i];
        for(int i=0;i<x;i++) np[idx++]=p[i];
        p=np;
    };

    for(int t=0; t<n-1; t++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        // Move element from pos to t
        // Strategy: first move to position 0, then move to position t

        // Move to position 0: use C part. op(0, n-pos) => element at pos goes to pos-(n-(n-pos))=pos-pos=0
        // Constraint: y=n-pos, x=0, x+y=n-pos>0 (true since pos<n), x+y<n means pos>0

        if(pos > 0){
            // Move to position 0
            apply_op(0, n-pos);
            // Now element is at position 0
            // Move from 0 to t: use A part. op(1, n-1-t) => element at 0 (in A, since 0<1) goes to (n-1)+0=n-1. That's not t.
            // Actually: op with x=1: element at pos 0 < x=1, so goes to (n-x)+0 = n-1. Not helpful directly.
            // op(0, n-t): element at 0. x=0, y=n-t. 0 >= n-y = t? Only if t==0. 
            // If t>0: element at 0 is in B (0 >= x=0 and 0 < n-y=t requires t>0). Goes to y+(0-x)=n-t. Not t.
            // Use: op(t+1, n-1-t). x+y=n-1+1-1=n... no. x=t+1,y=n-t-1, x+y=n. Invalid if n.
            // op(t, n-t-1): x+y=n-1<n. Element at 0<t(if t>0): in A, goes to n-t+0=n-t. Not t.
            // Just move to 0, then op(1,0) moves it to n-1. Then op(n-1-t,1) moves from n-1 to 0, then...
            if(t==0) continue; // already at 0
            apply_op(1, n-1-t); // elem at 0: in A(0<1), goes to n-1
            apply_op(n-1-t, 1); // elem at n-1: in C, goes to 0... then need to go to t
            apply_op(t, 0); // noop? x+y must be >0. t>0 ok. Elem at 0: 0<t, in A, goes to n-t. Hmm.
        } else {
            // pos==0, move to t
            if(t>0){
                apply_op(1, n-1-t);
                pos=n-1;
                apply_op(n-1-t,1);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
